343	    public void setGradeTerms(String grade, Integer terms) {
344	        if (terms == null) {
345	            gradeTerms.remove(grade);
346	        } else {
347	            gradeTerms.put(grade, terms);
348	        }
349	    }
350	
351	    /** The terms of a grade: its own, else the sheet's (the sheet's for no grade). */
352	    public int termsFor(String grade) {
353	        Integer own = grade == null ? null : gradeTerms.get(grade);
354	        return own != null ? own : terms;
355	    }
356	
357	    public BigDecimal getLatePct() {
358	        return latePct;
359	    }
360	
361	    public void setLatePct(BigDecimal latePct) {
362	        this.latePct = latePct;
363	    }
364	
365	    public LocalDate getPolicyDate() {
366	        return policyDate;
367	    }
368	
369	    public void setPolicyDate(LocalDate policyDate) {
370	        this.policyDate = policyDate;
371	    }
372	
373	    public LocalDate getPeriodNumberingFrom() {
374	        return periodNumberingFrom;
375	    }
376	
377	    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
378	        this.periodNumberingFrom = periodNumberingFrom;
379	    }
380	
381	    /** Whether a claim opened now is numbered within its period: the setting is a date and today is on or
382	     *  after it. */
383	    public boolean numbersByPeriod() {
384	        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
385	    }
386	
387	    /** How a claim dated on a date rounds its figures: half up before the policy date (the sheet's today
388	     *  when it has none), half to even on or after it. */
389	    public RoundingMode rounding(LocalDate date) {
390	        LocalDate policy = policyDate == null ? today : policyDate;
391	        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
392	    }
393	
394	    /** The late charge on an overdue claim's figure: the late percent of it for every full 30 days past its
395	     *  due-by on the sheet's today, rounded to cents as its date rounds; 0.00 for no figure (n/a). Only an
396	     *  OPEN or PENDING claim is overdue, so the caller asks only for those. */
397	    public BigDecimal lateCharge(BigDecimal figure, LocalDate dueBy, LocalDate date) {
398	        long late = ChronoUnit.DAYS.between(dueBy, today);
399	        if (figure == null || late < 30) {
400	            return BigDecimal.ZERO.setScale(2);
401	        }
402	        return figure.multiply(latePct).multiply(BigDecimal.valueOf(late / 30)).movePointLeft(2)
403	                .setScale(2, rounding(date));
404	    }
405	
406	    /** A live due as it counts: at least the floor; none (n/a) stays none. */
407	    public BigDecimal floored(BigDecimal due) {
408	        return due == null ? null : due.max(floor);
409	    }
410	
411	    /** Give out the sheet's next claim number. */
412	    public String nextClaimNumber() {
413	        return String.valueOf(++lastClaimNumber);
414	    }
415	}
