457	/** Loads sheets by id; a sheet never loaded before is started empty, its today the real date. */
458	@Service
459	public class SheetService {
460	
461	    private final SheetRepository sheets;
462	    private final ClaimSequenceRepository sequences;
463	    private final PeriodRepository periods;
464	    private final Rollup rollup;
465	    private final Audit audit;
466	
467	    public SheetService(SheetRepository sheets, ClaimSequenceRepository sequences, PeriodRepository periods,
468	            Rollup rollup, Audit audit) {
469	        this.sheets = sheets;
470	        this.sequences = sequences;
471	        this.periods = periods;
472	        this.rollup = rollup;
473	        this.audit = audit;
