476	    @Transactional
477	    public Sheet load(String id, String user) {
478	        return sheets.findById(id).orElseGet(() -> {
479	            try {
480	                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
481	            } catch (DataIntegrityViolationException e) {
482	                // Another user started the same sheet at the same moment.
483	                return sheets.findById(id).orElseThrow(() -> e);
484	            }
485	        });
486	    }
487	
488	    /** The sheet's today. Every date decision and default date in the sheet goes through this. */
489	    @Transactional(readOnly = true)
490	    public LocalDate today(String id) {
491	        return sheets.findById(id).map(Sheet::getToday).orElseThrow(SheetNotFoundException::new);
492	    }
493	
494	    /** Change the sheet's today, recording the figures it moves. */
495	    @Transactional
496	    public Sheet setToday(String id, String user, LocalDate today) {
497	        Sheet sheet = sheets.findById(id).orElseThrow(SheetNotFoundException::new);
498	        Rollup.Snapshot before = rollup.take(id);
499	        sheet.setToday(today);
500	        rollup.recordChanges(id, user, before);
501	        return sheet;
502	    }
