504	    /** Change the sheet's clerk limit: the largest due a clerk may settle; none for no limit. */
505	    @Transactional
506	    public Sheet setClerkLimit(String id, String user, BigDecimal limit) {
507	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
508	        sheet.setClerkLimit(limit == null ? null : limit.setScale(2));
509	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=clerk-limit value="
510	                + (sheet.getClerkLimit() == null ? "" : sheet.getClerkLimit().toPlainString()));
511	        return sheet;
512	    }
513	
514	    /** Change the sheet's floor: the least a claim's live due can be, recording the figures it moves. */
515	    @Transactional
516	    public Sheet setFloor(String id, String user, BigDecimal floor) {
517	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
518	        Rollup.Snapshot before = rollup.take(id);
519	        sheet.setFloor(floor.setScale(2));
520	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=floor value="
521	                + sheet.getFloor().toPlainString());
522	        rollup.recordChanges(id, user, before);
523	        return sheet;
524	    }
525	
526	    /** Change the sheet's terms: the number of days after a claim's date it is due by, for a claim added
527	     *  later whose grade has no terms of its own. A claim already added keeps its due-by. */
528	    @Transactional
529	    public Sheet setTerms(String id, String user, int terms) {
530	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
531	        sheet.setTerms(terms);
532	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=terms value=" + terms);
533	        return sheet;
534	    }
535	
536	    /** Change a grade's own terms (none: it uses the sheet's terms), for a claim added later. A claim already
537	     *  added keeps its due-by. */
538	    @Transactional
539	    public Sheet setGradeTerms(String id, String user, String grade, Integer terms) {
540	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
541	        sheet.setGradeTerms(grade, terms);
542	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=terms-" + grade + " value="
543	                + (terms == null ? "" : terms.toString()));
544	        return sheet;
545	    }
546	
547	    /** Change the sheet's late percent, recording the figures it moves. */
548	    @Transactional
549	    public Sheet setLatePct(String id, String user, BigDecimal latePct) {
550	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
551	        Rollup.Snapshot before = rollup.take(id);
552	        sheet.setLatePct(latePct.setScale(2));
553	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=late-pct value="
554	                + sheet.getLatePct().toPlainString());
555	        rollup.recordChanges(id, user, before);
556	        return sheet;
557	    }
558	
559	    /** Change the sheet's policy date (none: the sheet's today), recording the figures it moves. */
560	    @Transactional
561	    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
562	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
563	        Rollup.Snapshot before = rollup.take(id);
564	        sheet.setPolicyDate(policyDate);
565	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
566	                + (policyDate == null ? "" : policyDate.toString()));
567	        rollup.recordChanges(id, user, before);
568	        return sheet;
569	    }
570	
571	    /** Change the sheet's period numbering from-date (none: off). */
572	    @Transactional
573	    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
574	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
575	        sheet.setPeriodNumberingFrom(from);
576	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
577	                + (from == null ? "" : from.toString()));
578	        return sheet;
579	    }
580	
581	    /** The next number for a claim dated on a date: while the sheet numbers by period, the next in the
582	     *  sequence of the period containing the date (<period name>-1, -2, ...), or of no period (X-1, ...);
583	     *  otherwise the sheet-wide one (1, 2, ...). None is ever given twice. */
584	    @Transactional
585	    public String nextClaimNumber(String id, LocalDate date) {
586	        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
587	        if (!sheet.numbersByPeriod()) {
588	            return sheet.nextClaimNumber();
589	        }
590	        String prefix = periods.findBySheetIdOrderByFromDateAsc(id).stream()
591	                .filter(p -> p.contains(date)).findFirst().map(Period::getName).orElse("X");
592	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(id, prefix)
593	                .orElseGet(() -> new ClaimSequence(id, prefix));
594	        String number = sequence.nextClaimNumber();
595	        sequences.save(sequence);
596	        return number;
597	    }
598	}
599	package net.officefloor.hq.app.rollup;
600	
601	import java.math.BigDecimal;
602	import java.math.RoundingMode;
603	import java.time.LocalDate;
604	import java.util.Comparator;
605	import java.util.LinkedHashMap;
606	import java.util.List;
607	import java.util.Map;
608	import java.util.Objects;
609	import java.util.Optional;
610	import net.officefloor.hq.app.Audit;
611	import net.officefloor.hq.app.claim.Claim;
612	import net.officefloor.hq.app.claim.ClaimRepository;
613	import net.officefloor.hq.app.person.Person;
614	import net.officefloor.hq.app.person.PersonRepository;
615	import net.officefloor.hq.app.rate.Rate;
616	import net.officefloor.hq.app.rate.RateRepository;
617	import net.officefloor.hq.app.sheet.Sheet;
618	import net.officefloor.hq.app.sheet.SheetRepository;
619	import org.springframework.stereotype.Service;
620	
621	/**
622	 * Each person's claimed and due-total on a sheet, and the sheet's totals, as the screen shows them.
623	 * A change takes the figures before it, then records after its own audit lines a ROLLUP line for each
624	 * person whose figures moved (a person new to the sheet counting as moved), in the order they were
625	 * added, and a TOTALS line when the sheet's totals moved.
626	 */
627	@Service
628	public class Rollup {
629	
630	    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);
631	
632	    /** A person's figures; a null due-total is n/a. */
633	    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {
634	    }
635	
636	    /** Everyone's figures by person id, in the order they were added, and the sheet's totals. */
637	    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal) {
638	    }
639	
640	    private final PersonRepository people;
641	    private final ClaimRepository claims;
642	    private final RateRepository rates;
643	    private final SheetRepository sheets;
644	    private final Audit audit;
645	
646	    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
647	            Audit audit) {
648	        this.people = people;
649	        this.claims = claims;
650	        this.rates = rates;
651	        this.sheets = sheets;
652	        this.audit = audit;
653	    }
654	
655	    /** The sheet's figures now. */
656	    public Snapshot take(String sheetId) {
657	        Optional<Sheet> sheet = sheets.findById(sheetId);
658	        LocalDate today = sheet.map(Sheet::getToday).orElse(null);
659	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAsc(sheetId);
660	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
661	        Map<Long, Figures> figures = new LinkedHashMap<>();
662	        BigDecimal claimedTotal = ZERO;
663	        BigDecimal dueTotal = ZERO;
664	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
665	            BigDecimal claimed = ZERO;
666	            BigDecimal due = ZERO;
667	            boolean keptFigure = false;
668	            for (Claim claim : sheetClaims) {
669	                if (!claim.getPersonId().equals(person.getId()) || !countsLive(claim, person)) {
670	                    continue;
671	                }
672	                claimed = claimed.add(claim.getAmount());
673	                BigDecimal kept = claim.getSettledDue() != null ? claim.getSettledDue()
674	                        : claim.isBound() ? claim.getStatedDue() : null;
675	                if (kept != null) {
676	                    keptFigure = true;
677	                    due = due.add(charged(sheet, claim, kept));
678	                } else if (!claim.isBound()) {
679	                    // a claim priced at the grade in force on its date keeps a figure too
680	                    BigDecimal live = inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate())
681	                            .map(rate -> rated(sheet, claim, sheetClaims, rate))
682	                            .map(d -> floored(sheet, claim, d))
683	                            .orElse(null);
684	                    if (live != null) {
685	                        keptFigure = true;
686	                        due = due.add(charged(sheet, claim, live));
687	                    }
688	                }
689	            }
690	            boolean rated = today != null && inForce(sheetRates, person.gradeOn(today), today).isPresent();
691	            BigDecimal personDue = rated || keptFigure ? due : null;
692	            figures.put(person.getId(), new Figures(person.getName(), claimed, personDue));
693	            claimedTotal = claimedTotal.add(claimed);
694	            if (personDue != null) {
695	                dueTotal = dueTotal.add(personDue);
696	            }
697	        }
698	        return new Snapshot(figures, claimedTotal, dueTotal);
699	    }
700	
701	    /** The due-total of the claims that count dated from one date to another, both inclusive, as the
702	     *  screen shows a period's: each claim's settled due, else the figure its statement bound, else its
703	     *  live due, at least the floor, an overdue claim's late charge on top (a claim with no figure adds
704	     *  nothing). */
705	    public BigDecimal dueBetween(String sheetId, LocalDate from, LocalDate to) {
706	        Optional<Sheet> sheet = sheets.findById(sheetId);
707	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAsc(sheetId);
708	        Map<Long, Person> byId = new LinkedHashMap<>();
709	        people.findBySheetIdOrderByIdAsc(sheetId).forEach(p -> byId.put(p.getId(), p));
710	        BigDecimal total = ZERO;
711	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
712	        for (Claim claim : sheetClaims) {
713	            if (!countsLive(claim, byId.get(claim.getPersonId())) || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
714	                continue;
715	            }
716	            BigDecimal due;
717	            if (claim.getSettledDue() != null) {
718	                due = claim.getSettledDue();
719	            } else if (claim.isBound()) {
720	                due = claim.getStatedDue();
721	            } else {
722	                Person person = byId.get(claim.getPersonId());
723	                due = person == null ? null : inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate())
724	                        .map(rate -> rated(sheet, claim, sheetClaims, rate))
725	                        .map(d -> floored(sheet, claim, d))
726	                        .orElse(null);
727	            }
728	            if (due != null) {
729	                total = total.add(charged(sheet, claim, due));
730	            }
731	        }
732	        return total;
733	    }
734	
735	    /** Record, once the change commits, the lines for every figure that moved since {@code before}. */
736	    public void recordChanges(String sheetId, String user, Snapshot before) {
737	        Snapshot after = take(sheetId);
738	        String prefix = " sheet=" + sheetId + " by=" + user;
739	        after.people().forEach((id, now) -> {
740	            Figures was = before.people().get(id);
741	            if (was == null || was.claimed().compareTo(now.claimed()) != 0
742	                    || !sameDue(was.dueTotal(), now.dueTotal())) {
743	                audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name()
744	                        + " claimed=" + now.claimed().toPlainString() + " due-total=" + show(now.dueTotal()));
745	            }
746	        });
747	        if (before.claimedTotal().compareTo(after.claimedTotal()) != 0
748	                || before.dueTotal().compareTo(after.dueTotal()) != 0) {
749	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal().toPlainString()
750	                    + " due-total=" + after.dueTotal().toPlainString());
751	        }
752	    }
753	
754	    /** Whether a claim counts in the live totals: its status counts, and it is not left out by a hold. */
755	    private static boolean countsLive(Claim claim, Person person) {
756	        return claim.getStatus().counts() && !heldOut(claim, person);
757	    }
758	
759	    /** Whether a hold leaves a claim out of the live totals: it is OPEN or PENDING, bound by no statement,
760	     *  and dated within one of its person's holds. */
761	    public static boolean heldOut(Claim claim, Person person) {
762	        return person != null && claim.getStatus().isOpen() && !claim.isBound() && person.heldOn(claim.getDate());
763	    }
764	
765	    /** A claim's amount at a rate, divided by 100, rounded to cents as the claim's rounding date rounds on
766	     *  the sheet (half to even with no sheet). */
767	    private static BigDecimal rated(Optional<Sheet> sheet, Claim claim, List<Claim> sheetClaims, Rate rate) {
768	        LocalDate on = roundingDate(claim, sheetClaims);
769	        return claim.getAmount().multiply(rate.getRate()).movePointLeft(2)
770	                .setScale(2, sheet.map(s -> s.rounding(on)).orElse(RoundingMode.HALF_EVEN));
771	    }
772	
773	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it
774	     *  corrects (the claim of the same person with that number), its own when that is not found. */
775	    public static LocalDate roundingDate(Claim claim, List<Claim> sheetClaims) {
776	        if (!claim.isCorrection()) {
777	            return claim.getDate();
778	        }
779	        return sheetClaims.stream()
780	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
781	                .findFirst().map(Claim::getDate).orElse(claim.getDate());
782	    }
783	
784	    /** A live due as it counts: at least the sheet's floor, unless its claim is a correction. */
785	    private static BigDecimal floored(Optional<Sheet> sheet, Claim claim, BigDecimal due) {
786	        return claim.isCorrection() ? due : sheet.map(s -> s.floored(due)).orElse(due);
787	    }
788	
789	    /** A figure with its late charge on top while its claim is OPEN or PENDING (only those go overdue); a
790	     *  settled claim's due already holds the charge frozen in when it was settled. A correction has no
791	     *  late charge. */
792	    public static BigDecimal charged(Optional<Sheet> sheet, Claim claim, BigDecimal figure) {
793	        if (!claim.getStatus().isOpen() || claim.isCorrection()) {
794	            return figure;
795	        }
796	        return figure.add(sheet.map(s -> s.lateCharge(figure, claim.getDueBy(), claim.getDate())).orElse(ZERO));
797	    }
798	
799	    private static boolean sameDue(BigDecimal a, BigDecimal b) {
800	        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
801	    }
802	
803	    private static String show(BigDecimal due) {
804	        return due == null ? "n/a" : due.toPlainString();
805	    }
806	
807	    /** The grade's rate in force on a date: the latest from-date on or before it, none first; none
808	     *  when the date is after that rate's to-date. */
809	    private static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
810	        return sheetRates.stream()
811	                .filter(r -> r.getGrade().equals(grade))
812	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
813	                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
814	                .filter(r -> r.coversThrough(date));
815	    }
816	}
