  expect(await ui.reassign(pg_vic, c_ben_0, "Cam")).toBe(true);
  expect(await ui.claimAction(pg_vic, c_ben_0, "void")).toBe(true);
  expect(await ui.statement(pg_vic, p_cam)).toBe(true);
  const c_ben_0_2 = ui.must(await ui.addClaim(pg_vic, p_ben, {"amount": "10.35"}));
